//! Interface strings. tdesktop's English strings are built in (generated by
//! `tools/lang-gen`, with rgram's replacements from `rgram.strings`); a language
//! pack from TDLib (`localization_target` "tdesktop") overrides them by key.

mod english;
mod plural_rules;

pub use english::key;

/// A string key, such as [`key::lng_intro_next`].
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Key(u16);

impl Key {
    /// The key named `name` in tdesktop's `lang.strings`, without a `#form`
    /// suffix.
    #[must_use]
    pub fn from_name(name: &str) -> Option<Self> {
        english::NAMES
            .binary_search(&name)
            .ok()
            .and_then(|index| u16::try_from(index).ok())
            .map(Self)
    }

    #[must_use]
    pub fn name(self) -> &'static str {
        english::NAMES[self.index()]
    }

    fn index(self) -> usize {
        usize::from(self.0)
    }
}

/// CLDR plural categories, in tdesktop's order.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum PluralForm {
    Zero,
    One,
    Two,
    Few,
    Many,
    Other,
}

/// A string: plain text, or one text per [`PluralForm`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Value<S> {
    Text(S),
    Plural([S; 6]),
}

impl<S: AsRef<str>> Value<S> {
    fn get(&self, form: PluralForm) -> &str {
        match self {
            Self::Text(text) => text.as_ref(),
            Self::Plural(forms) => forms[form as usize].as_ref(),
        }
    }
}

/// The strings of one interface language.
#[derive(Debug, Clone)]
pub struct Strings {
    language: Box<str>,
    rule: plural_rules::Rule,
    pack: Vec<Option<Value<Box<str>>>>,
}

impl Default for Strings {
    fn default() -> Self {
        Self::english()
    }
}

impl Strings {
    /// The built-in English strings.
    #[must_use]
    pub fn english() -> Self {
        Self {
            language: "en".into(),
            rule: plural_rules::DEFAULT,
            pack: Vec::new(),
        }
    }

    /// `language`'s pack over the English strings. Keys rgram does not know
    /// are skipped; keys the pack lacks stay English.
    #[must_use]
    pub fn with_pack<K, S>(language: &str, values: impl IntoIterator<Item = (K, Value<S>)>) -> Self
    where
        K: AsRef<str>,
        S: Into<Box<str>>,
    {
        let mut pack = vec![None; english::NAMES.len()];
        for (name, value) in values {
            if let Some(key) = Key::from_name(name.as_ref()) {
                pack[key.index()] = Some(match value {
                    Value::Text(text) => Value::Text(text.into()),
                    Value::Plural(forms) => Value::Plural(forms.map(Into::into)),
                });
            }
        }
        Self {
            language: language.into(),
            rule: plural_rules::for_language(language),
            pack,
        }
    }

    /// The language code, such as `en` or `pt-br`.
    #[must_use]
    pub fn language(&self) -> &str {
        &self.language
    }

    /// The text of `key`; for a plural key, its "other" form.
    #[must_use]
    pub fn text(&self, key: Key) -> &str {
        self.pick(key, |_| PluralForm::Other)
    }

    /// The form of plural `key` that goes with `count`, as tdesktop picks it:
    /// pack values by the language's rule, built-in English by English's.
    #[must_use]
    pub fn plural(&self, key: Key, count: i64) -> &str {
        let n = i32::try_from(count.unsigned_abs()).unwrap_or(i32::MAX);
        self.pick(key, |rule| rule(n, n, 0, 0, 0, 0))
    }

    fn pick(&self, key: Key, form: impl FnOnce(plural_rules::Rule) -> PluralForm) -> &str {
        match self.pack.get(key.index()).and_then(Option::as_ref) {
            Some(value) => value.get(form(self.rule)),
            None => english::ENGLISH[key.index()].get(form(plural_rules::DEFAULT)),
        }
    }
}

/// Replaces each `{name}` in `template` with its value from `args`; unknown
/// placeholders stay as they are.
#[must_use]
pub fn fill(template: &str, args: &[(&str, &str)]) -> String {
    let mut out = String::with_capacity(template.len());
    let mut rest = template;
    while let Some(start) = rest.find('{') {
        out.push_str(&rest[..start]);
        let tail = &rest[start..];
        let replaced = tail.find('}').and_then(|end| {
            let name = &tail[1..end];
            args.iter()
                .find(|(arg, _)| *arg == name)
                .map(|(_, value)| (*value, end + 1))
        });
        match replaced {
            Some((value, consumed)) => {
                out.push_str(value);
                rest = &tail[consumed..];
            }
            None => {
                out.push('{');
                rest = &tail[1..];
            }
        }
    }
    out.push_str(rest);
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn english_comes_from_tdesktop() {
        let strings = Strings::english();
        assert_eq!(strings.text(key::lng_intro_next), "Next");
        assert_eq!(strings.text(key::rgram_app_name), "OxiGram");
        assert_eq!(Key::from_name("lng_intro_next"), Some(key::lng_intro_next));
        assert_eq!(key::lng_intro_next.name(), "lng_intro_next");
        assert_eq!(Key::from_name("lng_missing_key"), None);
    }

    #[test]
    fn english_plurals_use_one_and_other() {
        let strings = Strings::english();
        let key = key::lng_filter_unread_chats;
        assert_eq!(strings.plural(key, 1), "{text} ({count} unread chat)");
        assert_eq!(strings.plural(key, 2), "{text} ({count} unread chats)");
        assert_eq!(strings.plural(key, 0), "{text} ({count} unread chats)");
    }

    #[test]
    fn packs_override_by_key_with_their_plural_rule() {
        let forms = ["0", "one", "2", "few", "many", "other"].map(String::from);
        let strings = Strings::with_pack(
            "ru",
            [
                ("lng_intro_next", Value::Text("Далее".to_owned())),
                ("lng_filter_unread_chats", Value::Plural(forms)),
                ("lng_unknown", Value::Text("ignored".to_owned())),
            ],
        );
        assert_eq!(strings.text(key::lng_intro_next), "Далее");
        assert_eq!(strings.plural(key::lng_filter_unread_chats, 1), "one");
        assert_eq!(strings.plural(key::lng_filter_unread_chats, 3), "few");
        assert_eq!(strings.plural(key::lng_filter_unread_chats, 5), "many");
        assert_eq!(strings.plural(key::lng_filter_unread_chats, 21), "one");
        // Missing from the pack: English.
        assert_eq!(strings.text(key::lng_intro_finish), "Sign Up");
    }

    #[test]
    fn languages_without_rules_use_other() {
        let forms = ["0", "one", "2", "few", "many", "other"].map(String::from);
        let strings = Strings::with_pack("xx", [("lng_filter_unread_chats", Value::Plural(forms))]);
        assert_eq!(strings.plural(key::lng_filter_unread_chats, 1), "other");
        let regional = Strings::with_pack("pt-br", Vec::<(&str, Value<String>)>::new());
        assert_eq!(regional.language(), "pt-br");
    }

    #[test]
    fn fill_replaces_known_placeholders() {
        assert_eq!(
            fill(
                "Telegram will call you in {minutes}:{seconds}",
                &[("minutes", "1"), ("seconds", "05")]
            ),
            "Telegram will call you in 1:05"
        );
        assert_eq!(fill("{a} {b} {", &[("a", "x")]), "x {b} {");
    }
}
